package de.esolutions.connectedradioclient.data

/**
 * By using eTags we want to avoid unnecessary downloading of data.
 * The backend will check this eTags and only sends updated data.
 * These Strings will be generated by the backend and then persisted by the MetaDataService.
 */
data class ETags(
    val metadataETag: String?,
    val bearersETag: String?,
    val streamsETag: String?,
    val logoETag: String?,
    val logoSmallETag: String?
)